using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _sut = null!;

    [TestInitialize]
    public void Setup() => _sut = new ShoppingCart();

    // ── AddItem ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _sut.AddItem("SKU-1", 2, 9.99m);

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.AreEqual(2, _sut.Items["SKU-1"].Quantity);
        Assert.AreEqual(9.99m, _sut.Items["SKU-1"].Price);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantityAndUsesLatestPrice()
    {
        _sut.AddItem("SKU-1", 2, 5.00m);
        _sut.AddItem("SKU-1", 3, 6.00m);

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.AreEqual(5, _sut.Items["SKU-1"].Quantity);
        Assert.AreEqual(6.00m, _sut.Items["SKU-1"].Price);
    }

    [TestMethod]
    public void AddItem_MultipleSkus_AllTrackedIndependently()
    {
        _sut.AddItem("A", 1, 10m);
        _sut.AddItem("B", 2, 20m);

        Assert.AreEqual(2, _sut.Items.Count);
        Assert.AreEqual(1, _sut.Items["A"].Quantity);
        Assert.AreEqual(2, _sut.Items["B"].Quantity);
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero quantity")]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void AddItem_InvalidQuantity_ThrowsArgumentOutOfRange(int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _sut.AddItem("SKU-1", quantity, 5.00m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _sut.AddItem("SKU-1", 1, -1.00m));
    }

    [TestMethod]
    public void AddItem_NullSku_ThrowsArgumentNull()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _sut.AddItem(null!, 1, 5.00m));
    }

    // ── RemoveItem ───────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _sut.AddItem("SKU-1", 1, 10m);

        _sut.RemoveItem("SKU-1");

        Assert.AreEqual(0, _sut.Items.Count);
    }

    [TestMethod]
    public void RemoveItem_NonexistentSku_ThrowsKeyNotFound()
    {
        Assert.ThrowsException<KeyNotFoundException>(
            () => _sut.RemoveItem("MISSING"));
    }

    [TestMethod]
    public void RemoveItem_NullSku_ThrowsArgumentNull()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _sut.RemoveItem(null!));
    }

    [TestMethod]
    public void RemoveItem_OnlyRemovesTargetSku()
    {
        _sut.AddItem("A", 1, 10m);
        _sut.AddItem("B", 1, 20m);

        _sut.RemoveItem("A");

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.IsTrue(_sut.Items.ContainsKey("B"));
    }

    // ── CalculateTotal ───────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsQuantityTimesPrice()
    {
        _sut.AddItem("SKU-1", 3, 7.50m);

        Assert.AreEqual(22.50m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_SumsAll()
    {
        _sut.AddItem("A", 2, 10.00m);  // 20
        _sut.AddItem("B", 1, 5.00m);   // 5

        Assert.AreEqual(25.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemoval_ExcludesRemovedItem()
    {
        _sut.AddItem("A", 2, 10.00m);
        _sut.AddItem("B", 1, 5.00m);
        _sut.RemoveItem("A");

        Assert.AreEqual(5.00m, _sut.CalculateTotal());
    }

    // ── ApplyCoupon + CalculateTotal ─────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 90.00, DisplayName = "10% off")]
    [DataRow("SAVE20", 80.00, DisplayName = "20% off")]
    [DataRow("HALF", 50.00, DisplayName = "50% off")]
    public void CalculateTotal_WithKnownCoupon_AppliesDiscount(
        string coupon, double expectedDouble)
    {
        var expected = (decimal)expectedDouble;
        _sut.AddItem("SKU-1", 1, 100.00m);
        _sut.ApplyCoupon(coupon);

        Assert.AreEqual(expected, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_WithUnknownCoupon_NoDiscount()
    {
        _sut.AddItem("SKU-1", 1, 100.00m);
        _sut.ApplyCoupon("BOGUS");

        Assert.AreEqual(100.00m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_StoresCode()
    {
        _sut.ApplyCoupon("SAVE10");

        Assert.AreEqual("SAVE10", _sut.CouponCode);
    }

    [TestMethod]
    public void ApplyCoupon_ReplacesExistingCoupon()
    {
        _sut.ApplyCoupon("SAVE10");
        _sut.ApplyCoupon("SAVE20");

        Assert.AreEqual("SAVE20", _sut.CouponCode);
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null code")]
    [DataRow("", DisplayName = "Empty code")]
    [DataRow("   ", DisplayName = "Whitespace code")]
    public void ApplyCoupon_InvalidCode_Throws(string? code)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _sut.ApplyCoupon(code!));
    }

    [TestMethod]
    public void CalculateTotal_CouponOnMultipleItems_DiscountsEntireTotal()
    {
        _sut.AddItem("A", 2, 25.00m);  // 50
        _sut.AddItem("B", 1, 50.00m);  // 50
        _sut.ApplyCoupon("SAVE10");     // total 100 → 90

        Assert.AreEqual(90.00m, _sut.CalculateTotal());
    }

    // ── Zero-price edge case ─────────────────────────────────

    [TestMethod]
    public void AddItem_ZeroPrice_AllowedAndTotalReflectsIt()
    {
        _sut.AddItem("FREEBIE", 3, 0m);

        Assert.AreEqual(0m, _sut.CalculateTotal());
    }
}

